<template><view class="page safe-bottom"><view class="orders-heading"><view><text class="heading-title">我的订单</text><text class="heading-subtitle">查看预约进度与服务安排</text></view><uni-icons type="search" size="23" color="#628078" /></view><view class="tabs surface"><view v-for="tab in tabs" :key="tab.value" class="tab" :class="{ active: active === tab.value }" @click="active = tab.value">{{ tab.label }}</view></view><view v-if="!authStore.isLoggedIn" class="login-state surface"><view class="login-state-icon"><uni-icons type="person" size="36" color="#2e806d" /></view><text class="login-state-title">抱歉，您尚未登录！</text><text class="login-state-desc">登录后查看预约订单和服务进度</text><button class="login-outline" @click="goLogin">登录</button></view><view v-else-if="filtered.length" class="order-list"><view v-for="order in filtered" :key="order.orderId || order.orderNo" class="order-card surface" @click="openDetail(order)"><view class="order-head"><text class="order-no">{{ order.orderNo || order.orderId }}</text><text class="status" :class="`status--${order.orderStatus}`">{{ statusText(order.orderStatus) }}</text></view><view class="order-main"><view class="order-icon"><uni-icons type="home" size="26" color="#2e806d" /></view><view class="order-copy"><text class="service-name">{{ order.serviceName || '家政服务' }}</text><text class="order-time"><uni-icons type="calendar" size="14" color="#9aa9a5" /> {{ order.appointmentDate || '待确认日期' }} {{ order.slotName || '' }}</text></view><text class="amount">¥{{ order.amount || 0 }}</text></view><view v-if="order.orderStatus === '0'" class="order-actions"><button class="ghost-button" @click.stop="cancel(order)">取消预约</button><button class="primary-small" @click.stop="pay(order)">去支付</button></view><view v-else-if="order.orderStatus === '2'" class="order-actions"><button class="ghost-button" @click.stop="review(order)">评价服务</button></view></view></view><view v-else class="empty-panel surface"><view class="empty-icon"><uni-icons type="calendar" size="36" color="#2f806d" /></view><text class="empty-title">暂无相关订单</text><text class="muted">预约家政服务，生活更轻松</text><button class="primary-button" @click="goServices">去找服务</button></view><AppTabBar current-key="cart" /></view></template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import uniIcons from '@dcloudio/uni-ui/lib/uni-icons/uni-icons.vue'; import AppTabBar from '@/components/AppTabBar.vue'; import { cancelOrder, listOrders } from '@/api/service'; import { useAuthStore } from '@/stores/auth'
const authStore = useAuthStore(); const tabs = [{ label: '全部', value: '' }, { label: '待确认', value: '0' }, { label: '服务中', value: '1' }, { label: '已完成', value: '2' }]; const active = ref(''); const orders = ref([]); const filtered = computed(() => orders.value.filter(item => !active.value || String(item.orderStatus) === active.value))
onMounted(async () => { uni.setNavigationBarTitle({ title: '我的订单' }); if (!authStore.isLoggedIn) return; try { const response = await listOrders({ pageNum: 1, pageSize: 50 }); orders.value = response.rows || response.data?.rows || [] } catch (e) { uni.showToast({ title: e.message || '订单加载失败', icon: 'none' }) } })
function goLogin () { uni.navigateTo({ url: '/pages/login/index?redirect=/pages/orders/index' }) }
function requireLogin (callback) { if (authStore.isLoggedIn) return callback(); uni.showModal({ title: '登录后继续', content: '登录后可管理预约、支付和评价', confirmText: '去登录', success: ({ confirm }) => { if (confirm) goLogin() } }) }
function statusText (value) { return ({ 0: '待确认', 1: '服务中', 2: '已完成', 3: '已取消' })[value] || '待处理' }; function openDetail (order) { uni.navigateTo({ url: `/pages/order-detail/index?id=${order.orderId || order.orderNo}` }) }; function goServices () { uni.reLaunch({ url: '/pages/category/index' }) }; async function cancel (order) { requireLogin(async () => { const result = await new Promise(resolve => uni.showModal({ title: '取消预约', content: '确定取消这笔预约吗？', success: resolve })); if (!result.confirm) return; try { await cancelOrder(order.orderId); order.orderStatus = '3'; uni.showToast({ title: '已取消', icon: 'success' }) } catch (e) { uni.showToast({ title: e.message || '操作失败', icon: 'none' }) } }) }; function pay () { requireLogin(() => uni.showToast({ title: '支付功能由后台支付配置决定', icon: 'none' })) }; function review (order) { requireLogin(() => uni.navigateTo({ url: `/pages/review/index?id=${order.orderId}` })) }
</script><style lang="scss" scoped>
.orders-heading{display:flex;align-items:center;justify-content:space-between;padding:12rpx 4rpx 26rpx}.heading-title{display:block;color:#245d55;font-size:40rpx;font-weight:800}.heading-subtitle{display:block;margin-top:6rpx;color:#8aa69e;font-size:22rpx}.tabs{display:flex;padding:6rpx;margin-bottom:22rpx}.tab{flex:1;padding:18rpx 0;color:$app-muted;font-size:25rpx;text-align:center}.tab.active{color:#2e806d;font-weight:700;border-bottom:4rpx solid #43a68d}.order-card{margin-bottom:18rpx;padding:24rpx;border-radius:22rpx}.order-head,.order-main,.order-actions{display:flex;align-items:center}.order-head{justify-content:space-between;padding-bottom:18rpx;border-bottom:1rpx solid #edf1ef}.order-no{color:$app-muted;font-size:22rpx}.status{color:#2e806d;font-size:23rpx}.status--0{color:#d58a3f}.status--2{color:#8d9b98}.order-main{padding:22rpx 0}.order-icon{display:flex;align-items:center;justify-content:center;width:82rpx;height:82rpx;border-radius:20rpx;background:#e1f3ec}.order-copy{display:flex;flex:1;flex-direction:column;margin-left:18rpx}.service-name{color:$app-text;font-size:29rpx;font-weight:700}.order-time{display:flex;align-items:center;margin-top:10rpx;color:$app-muted;font-size:22rpx}.amount{color:#e6674d;font-size:31rpx;font-weight:800}.order-actions{justify-content:flex-end;gap:16rpx;padding-top:18rpx;border-top:1rpx solid #edf1ef}.ghost-button,.primary-small{padding:0 25rpx;line-height:60rpx;border-radius:12rpx;font-size:23rpx}.ghost-button{color:#72827d;background:#fff;border:1rpx solid #dce7e2}.primary-small{color:#fff;background:#2e806d}.empty-panel{display:flex;flex-direction:column;align-items:center;padding:90rpx 30rpx;text-align:center}.empty-icon{display:flex;align-items:center;justify-content:center;width:100rpx;height:100rpx;border-radius:30rpx;background:#e1f3ec}.empty-title{margin-top:24rpx;margin-bottom:10rpx;color:$app-text;font-size:30rpx;font-weight:700}.empty-panel .primary-button{width:260rpx;margin-top:28rpx;line-height:76rpx}
.login-state{display:flex;flex-direction:column;align-items:center;padding:100rpx 32rpx;text-align:center}.login-state-icon{display:flex;align-items:center;justify-content:center;width:104rpx;height:104rpx;border-radius:50%;background:#e1f3ec}.login-state-title{margin-top:26rpx;color:$app-text;font-size:30rpx;font-weight:700}.login-state-desc{margin-top:12rpx;color:$app-muted;font-size:23rpx}.login-outline{width:220rpx;margin-top:28rpx;line-height:70rpx;color:#2e806d;background:#fff;border:1rpx solid #2e806d;border-radius:14rpx}
</style>
